window.THREATS={"product": [{"id": "OT-S01", "c": "S", "t": "Spoofing of source across a zone / trust boundary", "d": "An attacker on the network path could impersonate the source and send traffic that the target accepts as genuine, because the communication crosses a trust boundary and the peer identity may not be verified.", "m": "Authenticate software processes and devices at the boundary (certificates or keys per device, not shared secrets). Reject traffic from unauthenticated peers. Allow-list expected peers on the conduit device.", "a": "T0849 Masquerading; T0848 Rogue Master", "r": "4-2 CR 1.2; 3-3 SR 1.2; 4-2 CR 1.8; 4-2 CR 1.9", "p": "High", "s": "SL 2", "fr": "FR1 Identification and authentication control", "i": "Loss of control; Manipulation of control", "f": "1"}, {"id": "OT-T01", "c": "T", "t": "Adversary-in-the-middle tampering of source to target traffic", "d": "Traffic between the source and the target crosses a trust boundary without integrity protection, so an attacker in the path could modify values, commands or responses without detection.", "m": "Use protocol security with message integrity (OPC UA Sign/SignAndEncrypt, CIP Security, DNP3-SA, IEC 62351, TLS). Where the protocol cannot be secured, tunnel it through an authenticated, integrity-protected conduit (IPsec/TLS) and restrict paths at the zone boundary.", "a": "T0830 Adversary-in-the-Middle; T0831 Manipulation of Control; T0832 Manipulation of View", "r": "4-2 CR 3.1; 3-3 SR 3.1; 4-2 CR 4.3", "p": "High", "s": "SL 2", "fr": "FR3 System integrity", "i": "Manipulation of control; Manipulation of view; Safety", "f": "1"}, {"id": "OT-I01", "c": "I", "t": "Sniffing of operational data between source and target", "d": "Traffic between the source and the target is not encrypted across the trust boundary. An attacker could capture process values, tag names, program contents or credentials and use them to plan an attack.", "m": "Encrypt flows that cross zone boundaries where confidentiality is required (TLS, OPC UA SignAndEncrypt, IPsec tunnels). Classify data to decide where encryption is needed. Do not send credentials over unencrypted channels.", "a": "T0842 Network Sniffing; T0861 Point & Tag Identification; T0882 Theft of Operational Information", "r": "4-2 CR 4.1; 4-2 CR 4.3; 3-3 SR 4.1", "p": "Medium", "s": "SL 2", "fr": "FR4 Data confidentiality", "i": "Confidentiality / IP; Attack enablement", "f": "1"}, {"id": "OT-I02", "c": "I", "t": "Credentials or keys exposed on the source to target flow", "d": "The flow may carry passwords, keys or sensitive IP without encryption. Captured credentials allow an attacker to log in as a legitimate user or device.", "m": "Never transmit authenticators in cleartext. Use encrypted, mutually authenticated channels. Prefer challenge-response or certificate-based authentication. Rotate any credential that has been sent in cleartext.", "a": "T0842 Network Sniffing; T0859 Valid Accounts", "r": "4-2 CR 4.1; 4-2 CR 1.5; 4-2 CR 4.3", "p": "High", "s": "SL 1", "fr": "FR4 Data confidentiality", "i": "Unauthorized access", "f": "1"}, {"id": "OT-T02", "c": "T", "t": "Replay or injection of control commands to target", "d": "Commands, setpoints or logic sent to the target are not authenticated, so recorded or crafted messages could be replayed or injected to operate equipment.", "m": "Protect session integrity with authenticated sessions, sequence numbers / nonces and timestamps (CR 3.8). Use protocol security with anti-replay (DNP3-SA, CIP Security, OPC UA). Validate that commands come from authorised masters only.", "a": "T1692.001 Unauthorized Message: Command Message; T0831 Manipulation of Control", "r": "4-2 CR 3.1; 4-2 CR 3.8; 4-2 CR 2.1", "p": "High", "s": "SL 2", "fr": "FR3 System integrity", "i": "Loss of control; Equipment damage; Safety", "f": "1"}, {"id": "OT-D01", "c": "D", "t": "Network flooding of target from another zone", "d": "the target receives traffic from across a trust boundary. A flood, malformed-packet storm or resource-exhaustion attack could degrade or stop its essential functions.", "m": "Rate-limit and filter at the conduit. Design the component to keep essential functions running under load (CR 7.1) and test with network robustness tests (e.g. ISASecure CRT, Achilles-type storm tests). Separate control and management traffic.", "a": "T0814 Denial of Service; T0826 Loss of Availability", "r": "4-2 CR 7.1; 4-2 CR 7.2; 3-3 SR 7.1", "p": "Medium", "s": "SL 1", "fr": "FR7 Resource availability", "i": "Loss of availability; Loss of control; Loss of view", "f": "3"}, {"id": "OT-R01", "c": "R", "t": "Security-relevant actions on target not audited", "d": "Requests that reach the target from another zone may not produce audit records, so changes, logins or failures could not be attributed or investigated.", "m": "Generate audit records for access control, configuration changes, request errors and control-system events (CR 2.8) with accurate timestamps (CR 2.11). Make logs available to a central collector (CR 6.1).", "a": "T0872 Indicator Removal on Host", "r": "4-2 CR 2.8; 4-2 CR 2.11; 4-2 CR 6.1", "p": "Medium", "s": "SL 1", "fr": "FR2 Use control", "i": "Forensics; Compliance", "f": "3"}, {"id": "OT-E01", "c": "E", "t": "Non-essential services on target reachable across the boundary", "d": "Ports, services or debug functions on the target that are not needed for its function may be reachable from another zone and give an attacker extra attack surface.", "m": "Apply least functionality (CR 7.7): disable unused ports, services and protocols by default. Document required ports in the security guidelines. Allow only required flows at the conduit.", "a": "T0866 Exploitation of Remote Services; T0846 Remote System Discovery", "r": "4-2 CR 7.7; 4-2 CR 7.6; 4-2 NDR 5.2", "p": "Medium", "s": "SL 1", "fr": "FR7 Resource availability", "i": "Attack enablement", "f": "3"}, {"id": "OT-I03", "c": "I", "t": "Reconnaissance of target (device fingerprinting, enumeration)", "d": "An attacker could query the target across the boundary to identify vendor, model, firmware version, I/O modules and tags and so pick known vulnerabilities.", "m": "Limit information returned to unauthenticated requests. Require authentication for diagnostic and identification services where feasible. Detect scanning at the boundary.", "a": "T0888 Remote System Information Discovery; T0846 Remote System Discovery", "r": "4-2 CR 7.7; 4-2 CR 2.1; 4-2 CR 6.2", "p": "Low", "s": "SL 2", "fr": "FR7 Resource availability", "i": "Attack enablement", "f": "3"}, {"id": "OT-T03", "c": "T", "t": "Unauthorized program / logic download to target", "d": "An attacker with network access could download modified control logic or tasking to the target, changing how it controls the process (e.g. Stuxnet, TRITON).", "m": "Require authentication and authorisation for program download, online edits and forcing (CR 2.1). Support a physical or logical write-protect / run-lock. Sign or integrity-check project files (CR 3.4). Log and alarm on every logic change.", "a": "T0843 Program Download; T0821 Modify Controller Tasking; T0889 Modify Program; T0827 Loss of Control; T0879 Damage to Property", "r": "4-2 CR 2.1; 4-2 CR 3.4; 4-2 CR 2.8", "p": "High", "s": "SL 1", "fr": "FR2 Use control", "i": "Loss of control; Safety; Equipment damage", "f": "2"}, {"id": "OT-E02", "c": "E", "t": "Unauthorized change of operating mode on target", "d": "A remote command could switch the target between Run, Program, Remote or Test modes without authorisation, enabling logic changes or stopping control.", "m": "Require authorisation for mode changes. Provide a physical key switch or local confirmation for Program mode. Report the current mode to the HMI and alarm on unexpected changes.", "a": "T0858 Change Operating Mode; T0868 Detect Operating Mode", "r": "4-2 CR 2.1; 4-2 CR 2.8", "p": "High", "s": "SL 1", "fr": "FR2 Use control", "i": "Loss of control; Loss of availability", "f": "2"}, {"id": "OT-D02", "c": "D", "t": "Remote restart, shutdown or stop of target", "d": "Protocol commands (stop CPU, reset, reboot) could be sent to the target to halt control of the process.", "m": "Require authorisation for stop/reset services. Make these services configurable and disabled by default where possible. Ensure outputs go to a defined safe state on stop (CR 3.6).", "a": "T0816 Device Restart/Shutdown; T0813 Denial of Control; T0881 Service Stop", "r": "4-2 CR 7.1; 4-2 CR 2.1; 4-2 CR 3.6", "p": "High", "s": "SL 1", "fr": "FR7 Resource availability", "i": "Loss of production; Loss of control", "f": "2"}, {"id": "OT-I04", "c": "I", "t": "Program upload / theft of control logic from target", "d": "An attacker could upload the program and configuration from the target to steal know-how or study the process before an attack.", "m": "Require authorisation for program upload. Support know-how protection (encrypted / protected blocks). Log upload events.", "a": "T0845 Program Upload; T0882 Theft of Operational Information", "r": "4-2 CR 4.1; 4-2 CR 2.1", "p": "Medium", "s": "SL 2", "fr": "FR4 Data confidentiality", "i": "Confidentiality / IP; Attack enablement", "f": "2"}, {"id": "OT-T04", "c": "T", "t": "Setpoint or parameter on target changed to unsafe values", "d": "Parameters, setpoints or limits on the target could be changed to values outside the safe operating envelope.", "m": "Validate all inputs against engineering limits (CR 3.5). Separate permissions for operator setpoints and engineering parameters. Keep hard limits in logic or in an independent safety layer, not only in the HMI.", "a": "T0836 Modify Parameter; T0831 Manipulation of Control; T0827 Loss of Control; T0879 Damage to Property", "r": "4-2 CR 3.5; 4-2 CR 2.1; 4-2 CR 3.6", "p": "High", "s": "SL 1", "fr": "FR3 System integrity", "i": "Safety; Equipment damage; Product quality", "f": "2"}, {"id": "OT-T05", "c": "T", "t": "Manipulation of I/O image or forcing of points on target", "d": "An attacker could force inputs or outputs, or overwrite the I/O image, so the target acts on false values or drives outputs directly.", "m": "Restrict force and I/O override functions to authorised engineering roles. Show active forces on the HMI. Log and alarm on force events.", "a": "T0835 Manipulate I/O Image; T0806 Brute Force I/O", "r": "4-2 CR 2.1; 4-2 CR 2.8", "p": "Medium", "s": "SL 2", "fr": "FR2 Use control", "i": "Manipulation of control; Safety", "f": "2"}, {"id": "OT-T06", "c": "T", "t": "Malicious or modified firmware loaded on target", "d": "Firmware for the target could be replaced with a modified image that hides malicious behaviour or bricks the device.", "m": "Accept only firmware signed by the product supplier and verify the signature on the device before install (CR 3.4, EDR 3.10). Prevent rollback to vulnerable versions. Require authorisation to start firmware update mode.", "a": "T1693.002 Modify Firmware: Module Firmware; T1693.001 Modify Firmware: System Firmware; T0800 Activate Firmware Update Mode", "r": "4-2 CR 3.4; 4-2 EDR 3.10; 4-2 EDR 3.14", "p": "High", "s": "SL 1", "fr": "FR3 System integrity", "i": "Loss of control; Persistent compromise", "f": "3"}, {"id": "OT-T07", "c": "T", "t": "Boot process or runtime integrity of target bypassed", "d": "Without a verified boot chain, an attacker who can write to flash could run persistent unsigned code on the target.", "m": "Implement secure / measured boot from a hardware root of trust (EDR 3.14). Provision supplier and asset-owner roots of trust securely (EDR 3.12, 3.13). Verify security functions at start-up (CR 3.3).", "a": "T1693.001 Modify Firmware: System Firmware; T0851 Rootkit", "r": "4-2 EDR 3.14; 4-2 EDR 3.12; 4-2 EDR 3.13; 4-2 CR 3.3", "p": "Medium", "s": "SL 2", "fr": "FR3 System integrity", "i": "Persistent compromise", "f": "3"}, {"id": "OT-D03", "c": "D", "t": "target outputs not driven to a safe state when attacked or failing", "d": "If the target is overloaded, crashes or loses communication, its outputs may hold an unsafe state or behave unpredictably.", "m": "Define deterministic fail-safe output behaviour (CR 3.6) and safe error handling (CR 3.7). Use communication watchdogs. Test behaviour under network storms and malformed traffic.", "a": "T0813 Denial of Control; T0826 Loss of Availability; T0827 Loss of Control; T0879 Damage to Property", "r": "4-2 CR 3.6; 4-2 CR 3.7; 4-2 CR 7.1", "p": "High", "s": "SL 1", "fr": "FR3 System integrity", "i": "Safety; Equipment damage", "f": "3"}, {"id": "OT-D04", "c": "D", "t": "Network load disturbs the scan cycle of target", "d": "Communication processing on the target may share CPU with the control task, so heavy or malformed traffic could increase scan time and miss control deadlines.", "m": "Prioritise the control task over communication (CR 7.2 resource management). Limit connections and request rates. Test with load and robustness testing at all supported SLs.", "a": "T0814 Denial of Service", "r": "4-2 CR 7.1; 4-2 CR 7.2", "p": "Medium", "s": "SL 1", "fr": "FR7 Resource availability", "i": "Loss of control; Product quality", "f": "3"}, {"id": "OT-T08", "c": "T", "t": "Physical tampering with target", "d": "Someone with physical access to the target could open the enclosure, replace modules, insert hardware implants or connect to internal buses.", "m": "Provide tamper resistance and tamper detection with alarming (EDR 3.11, required from SL 2). Use sealed enclosures and locked cabinets. Report tamper events to the monitoring system.", "a": "T1693.002 Modify Firmware: Module Firmware (via physical access)", "r": "4-2 EDR 3.11; 4-2 CR 2.8", "p": "Medium", "s": "SL 2", "fr": "FR3 System integrity", "i": "Persistent compromise; Loss of control", "f": "3"}, {"id": "OT-E03", "c": "E", "t": "Debug or service interface on target gives privileged access", "d": "JTAG, UART consoles, USB service ports or test modes on the target could give root access, bypass authentication or dump firmware.", "m": "Disable or lock debug interfaces in production (EDR/HDR/NDR 2.13). Protect service ports with authentication. Document any remaining interfaces in the security guidelines.", "a": "T1693.002 Modify Firmware: Module Firmware; T1693.001 Modify Firmware: System Firmware", "r": "4-2 EDR 2.13; 4-2 HDR 2.13; 4-2 NDR 2.13", "p": "High", "s": "SL 1", "fr": "FR2 Use control", "i": "Full compromise", "f": "3"}, {"id": "OT-I05", "c": "I", "t": "Extraction of keys or credentials from target", "d": "Keys, certificates or passwords stored on the target could be read from flash or memory, letting an attacker impersonate the device or decrypt traffic from many devices.", "m": "Store private keys in a secure element / TPM or protected memory. Use unique keys per device, never fleet-wide secrets. Erase secrets on decommissioning (CR 4.2).", "a": "T1694.002 Insecure Credentials: Hardcoded Credentials; T0859 Valid Accounts", "r": "4-2 CR 4.1; 4-2 CR 1.5; 4-2 CR 4.2; 4-2 EDR 3.11", "p": "High", "s": "SL 2", "fr": "FR4 Data confidentiality", "i": "Fleet-wide compromise", "f": "3"}, {"id": "OT-S02", "c": "S", "t": "Rogue master or rogue device on the fieldbus to target", "d": "A device connected to the fieldbus or serial link could act as a rogue master or slave, sending commands to or impersonating devices that the target trusts.", "m": "Restrict physical access to fieldbus segments. Use protocols with device authentication where available. Monitor for unexpected masters or addresses. Allow-list device addresses.", "a": "T0848 Rogue Master; T1692.002 Unauthorized Message: Reporting Message", "r": "4-2 CR 1.2; 3-3 SR 1.2", "p": "High", "s": "SL 2", "fr": "FR1 Identification and authentication control", "i": "Manipulation of control", "f": "1"}, {"id": "OT-T09", "c": "T", "t": "Spoofed measurement or status reported from source", "d": "Values reported from the source to the target could be falsified, so the control system acts on wrong process data or operators see false conditions.", "m": "Authenticate devices and protect message integrity. Apply plausibility and cross-checks on critical measurements (redundant sensors, rate-of-change limits). Keep independent safety measurements for safety functions.", "a": "T1692.002 Unauthorized Message: Reporting Message; T0832 Manipulation of View", "r": "4-2 CR 3.1; 4-2 CR 3.5; 4-2 CR 1.2", "p": "High", "s": "SL 2", "fr": "FR3 System integrity", "i": "Manipulation of view; Safety", "f": "5"}, {"id": "OT-T10", "c": "T", "t": "Unauthorized modification of safety logic or configuration on target", "d": "An attacker could change safety logic, trip points or configuration on the target, so a hazardous event is not prevented (e.g. TRITON/TRISIS).", "m": "Require authorisation plus a physical key / local confirmation for safety program changes. Verify logic signatures. Keep the SIS engineering workstation in the safety zone and offline when not in use. Perform the SIS security risk assessment required by IEC 61511-1 clause 8.2.4.", "a": "T0880 Loss of Safety; T0837 Loss of Protection; T0889 Modify Program; T0827 Loss of Control; T0879 Damage to Property", "r": "4-2 CR 3.4; 4-2 CR 2.1; IEC 61511-1 8.2.4", "p": "High", "s": "SL 3", "fr": "FR3 System integrity", "i": "Safety; Environmental; Equipment damage", "f": "2"}, {"id": "OT-E04", "c": "E", "t": "Bypass, override or inhibit of safety function on target", "d": "Remote bypass, maintenance override or mode-change commands could disable the safety function of the target while the process is running.", "m": "Allow bypass and override only locally or with dual authorisation. Alarm and time-limit all bypasses. Show bypass status on the HMI and log it.", "a": "T0858 Change Operating Mode; T0837 Loss of Protection; T0878 Alarm Suppression; T0827 Loss of Control; T0879 Damage to Property", "r": "4-2 CR 2.1; 4-2 CR 2.8; IEC 61511", "p": "High", "s": "SL 3", "fr": "FR2 Use control", "i": "Safety", "f": "2"}, {"id": "OT-E05", "c": "E", "t": "Compromise of the control network reaches safety function target", "d": "the target accepts traffic from outside its zone. A compromise of the BPCS or another zone could then affect the safety function (loss of independence).", "m": "Place safety functions in a separate zone. Allow only read-only or tightly controlled write flows from the BPCS. Use a dedicated conduit device with protocol filtering. Keep safety and non-safety functions independent (IEC 61511 layers of protection).", "a": "T0880 Loss of Safety; T0886 Remote Services", "r": "3-3 SR 5.1; 3-3 SR 5.2; 4-2 CR 5.1", "p": "High", "s": "SL 3", "fr": "FR5 Restricted data flow", "i": "Safety", "f": "2"}, {"id": "OT-T11", "c": "T", "t": "Deliberate manipulation of safety communication to target", "d": "Safety protocols (PROFIsafe, CIP Safety, FSoE) detect random errors on a black channel but are not designed against an intelligent attacker who can forge valid safety frames.", "m": "Treat the safety channel as needing security: isolate it in the safety zone, block access from other zones, and add cryptographic protection where the protocol supports it. Include deliberate attacks in the safety/security co-engineering analysis.", "a": "T0830 Adversary-in-the-Middle; T0880 Loss of Safety", "r": "4-2 CR 3.1; 3-3 SR 5.1; IEC 61784-3", "p": "High", "s": "SL 3", "fr": "FR3 System integrity", "i": "Safety", "f": "1"}, {"id": "OT-T12", "c": "T", "t": "Manipulation of view on target", "d": "Process values, alarms or status shown by the target could be falsified, so operators do not see or misjudge the real process state.", "m": "Protect integrity of data from controllers (CR 3.1). Protect HMI graphics and tag databases against modification (CR 3.4). Provide independent indications for critical variables.", "a": "T0832 Manipulation of View; T1692.002 Unauthorized Message: Reporting Message", "r": "4-2 CR 3.1; 4-2 CR 3.4", "p": "High", "s": "SL 2", "fr": "FR3 System integrity", "i": "Manipulation of view; Safety", "f": "2"}, {"id": "OT-D05", "c": "D", "t": "Loss of view on target", "d": "the target could be made unavailable or frozen so operators lose visibility of the process.", "m": "Provide redundancy for essential HMI/SCADA functions. Support fast recovery from known-good images (CR 7.4). Make frozen displays detectable (heartbeat / live indicator).", "a": "T0815 Denial of View; T0829 Loss of View", "r": "4-2 CR 7.1; 4-2 CR 7.3; 4-2 CR 7.4", "p": "High", "s": "SL 1", "fr": "FR7 Resource availability", "i": "Loss of view; Loss of production", "f": "2"}, {"id": "OT-T13", "c": "T", "t": "Alarm suppression or modification on target", "d": "Alarm limits, priorities or notifications on the target could be changed or suppressed to hide an attack or abnormal process condition.", "m": "Restrict alarm configuration to authorised roles. Log and report alarm configuration changes. Monitor for unexpected alarm shelving / suppression.", "a": "T0878 Alarm Suppression; T0838 Modify Alarm Settings", "r": "4-2 CR 2.1; 4-2 CR 2.8", "p": "Medium", "s": "SL 2", "fr": "FR2 Use control", "i": "Safety; Loss of view", "f": "2"}, {"id": "OT-E06", "c": "E", "t": "Missing or weak role-based access control on target", "d": "Users of the target could perform actions beyond their role (e.g. operators changing engineering parameters) if authorisation is not enforced per role.", "m": "Enforce role-based authorisation for all human users (CR 2.1), with least privilege and separation between operator, engineer and administrator roles. Support supervisor override for essential operations.", "a": "T0859 Valid Accounts; T0890 Exploitation for Privilege Escalation", "r": "4-2 CR 2.1; 4-2 CR 1.3", "p": "High", "s": "SL 1", "fr": "FR2 Use control", "i": "Unauthorized control", "f": "2"}, {"id": "OT-R02", "c": "R", "t": "Actions by source on target cannot be attributed", "d": "If the source uses shared or generic accounts on the target, actions cannot be traced to an individual.", "m": "Uniquely identify and authenticate all human users (CR 1.1). Record user identity in audit records (CR 2.8). Use non-repudiation for critical actions where required at SL 3+ (CR 2.12).", "a": "T0859 Valid Accounts", "r": "4-2 CR 2.8; 4-2 CR 1.1; 4-2 CR 2.12", "p": "Medium", "s": "SL 1", "fr": "FR2 Use control", "i": "Forensics; Compliance", "f": "5"}, {"id": "OT-T14", "c": "T", "t": "Malware execution on target", "d": "the target could be infected with malware via network, removable media, phishing or vendor tools.", "m": "Support malware protection appropriate to the platform: application allow-listing, OS hardening or validated anti-malware (HDR/SAR 3.2). Only run signed code. Document compatible security software in the guidelines.", "a": "T0863 User Execution; T1701 Command and Scripting Interpreter; T0865 Spearphishing Attachment", "r": "4-2 HDR 3.2; 4-2 SAR 3.2; 4-2 CR 3.4", "p": "High", "s": "SL 1", "fr": "FR3 System integrity", "i": "Full compromise", "f": "4"}, {"id": "OT-D06", "c": "D", "t": "Ransomware or destructive malware disables target", "d": "Ransomware or wiper malware could encrypt or destroy the target and its data, stopping production (e.g. NotPetya, Colonial Pipeline effects).", "m": "Support backup of configuration and data (CR 7.3) and documented, tested recovery to a known secure state (CR 7.4). Limit lateral movement through segmentation and least privilege. Keep offline backups.", "a": "T0809 Data Destruction; T0828 Loss of Productivity and Revenue; T0826 Loss of Availability", "r": "4-2 CR 7.3; 4-2 CR 7.4; 3-3 SR 5.1", "p": "High", "s": "SL 1", "fr": "FR7 Resource availability", "i": "Loss of production; Financial", "f": "4"}, {"id": "OT-E07", "c": "E", "t": "Exploitation of unpatched / legacy platform of target", "d": "the target may run on an OS or runtime that is out of support or rarely patched, exposing known vulnerabilities.", "m": "Support the product on maintained platforms. Provide a patch qualification and delivery process (4-1 SUM) and timely security updates (HDR 3.10). Define compensating countermeasures for legacy deployments in the security guidelines.", "a": "T0866 Exploitation of Remote Services; T0890 Exploitation for Privilege Escalation", "r": "4-2 HDR 3.10; 4-1 SUM; 4-1 SG", "p": "High", "s": "SL 1", "fr": "FR3 System integrity", "i": "Full compromise", "f": "4"}, {"id": "OT-T15", "c": "T", "t": "Project file infection via target", "d": "Engineering projects handled by the target could be infected or modified so malicious logic is downloaded to controllers.", "m": "Integrity-protect project files (signatures / hashes, CR 3.4). Show differences before download. Validate project files on open. Keep engineering tools patched and isolated.", "a": "T0873 Project File Infection; T0889 Modify Program", "r": "4-2 CR 3.4; 4-2 SAR 3.2", "p": "High", "s": "SL 2", "fr": "FR3 System integrity", "i": "Loss of control; Safety", "f": "2"}, {"id": "OT-I06", "c": "I", "t": "Theft of engineering / operational information from target", "d": "Projects, network diagrams, tag lists or historical data on the target could be exfiltrated and used to plan an attack or steal IP.", "m": "Encrypt sensitive data at rest (CR 4.1). Restrict read access by role. Monitor large exports. Classify engineering data.", "a": "T0882 Theft of Operational Information; T0811 Data from Information Repositories; T0893 Data from Local System", "r": "4-2 CR 4.1; 4-2 CR 2.1", "p": "Medium", "s": "SL 2", "fr": "FR4 Data confidentiality", "i": "Confidentiality / IP; Attack enablement", "f": "2"}, {"id": "OT-E08", "c": "E", "t": "Compromised source used to control target", "d": "the source holds the privileges to program and configure the target. If it is compromised, an attacker inherits full control over the controller.", "m": "Make {target.Name} authenticate the engineering tool and user, not only the network address (CR 1.2, CR 1.1). Require re-authentication for critical operations. Harden and isolate engineering workstations; connect them only when needed.", "a": "T0843 Program Download; T0886 Remote Services; T0859 Valid Accounts", "r": "4-2 CR 1.1; 4-2 CR 1.2; 4-2 CR 2.1", "p": "High", "s": "SL 2", "fr": "FR1 Identification and authentication control", "i": "Loss of control; Safety", "f": "5"}, {"id": "OT-E09", "c": "E", "t": "Web application vulnerabilities in target", "d": "The web interface of the target could be vulnerable to injection, XSS, CSRF, path traversal or authentication bypass, leading to device takeover.", "m": "Apply secure coding (OWASP ASVS) and input validation (CR 3.5). Use CSRF tokens, secure headers and HTTPS only. Perform web penetration testing and static analysis (4-1 SVV).", "a": "T0819 Exploit Public-Facing Application; T0866 Exploitation of Remote Services", "r": "4-2 CR 3.5; 4-2 CR 2.1; 4-1 SI; 4-1 SVV", "p": "High", "s": "SL 1", "fr": "FR3 System integrity", "i": "Full compromise", "f": "2"}, {"id": "OT-S03", "c": "S", "t": "Session hijacking on the target web interface", "d": "Session tokens for the target could be stolen or fixed, allowing an attacker to act as a logged-in user.", "m": "Protect session integrity (CR 3.8): random session IDs, secure/HttpOnly cookies, invalidate on logout. Session lock after inactivity (CR 2.5) and remote session termination (CR 2.6).", "a": "T0859 Valid Accounts", "r": "4-2 CR 3.8; 4-2 CR 2.5; 4-2 CR 2.6", "p": "Medium", "s": "SL 2", "fr": "FR3 System integrity", "i": "Unauthorized access", "f": "2"}, {"id": "OT-T16", "c": "T", "t": "Mobile code or script injection in target", "d": "Scripts, macros or mobile code (JavaScript, VBA, HMI scripts) executed by the target could be injected or modified.", "m": "Control mobile code (SAR 2.4): allow only authorised, integrity-checked scripts. Disable scripting features that are not needed.", "a": "T1701 Command and Scripting Interpreter; T0871 Execution through API", "r": "4-2 SAR 2.4; 4-2 CR 3.4", "p": "Medium", "s": "SL 1", "fr": "FR2 Use control", "i": "Full compromise", "f": "2"}, {"id": "OT-E10", "c": "E", "t": "Kiosk / HMI break-out to the underlying OS of target", "d": "A user at the target could escape the HMI shell (dialogs, help files, keyboard shortcuts) to the desktop and gain OS-level access.", "m": "Harden kiosk mode: block shortcuts, file dialogs and shell access. Run HMI under a least-privilege account. Apply least functionality to the host (CR 7.7).", "a": "T0823 Graphical User Interface", "r": "4-2 CR 2.1; 4-2 CR 7.7", "p": "Medium", "s": "SL 1", "fr": "FR2 Use control", "i": "Full compromise", "f": "5"}, {"id": "OT-I07", "c": "I", "t": "Verbose errors or diagnostics disclose internals of target", "d": "Error messages, stack traces or diagnostic pages from the target could reveal versions, paths or configuration useful to an attacker.", "m": "Return error information that supports operation without exposing internals (CR 3.7). Restrict diagnostic data to authenticated users.", "a": "T0888 Remote System Information Discovery", "r": "4-2 CR 3.7", "p": "Low", "s": "SL 1", "fr": "FR3 System integrity", "i": "Attack enablement", "f": "2"}, {"id": "OT-S04", "c": "S", "t": "Default, shared or hard-coded credentials on target", "d": "the target could ship with default, shared or hard-coded passwords or keys that attackers can find in manuals or firmware.", "m": "No hard-coded credentials. Force change of default credentials at commissioning (CR 1.5). Enforce password strength (CR 1.7). Support unique per-device credentials.", "a": "T1694.001 Insecure Credentials: Default Credentials; T1694.002 Insecure Credentials: Hardcoded Credentials", "r": "4-2 CR 1.1; 4-2 CR 1.5; 4-2 CR 1.7", "p": "High", "s": "SL 1", "fr": "FR1 Identification and authentication control", "i": "Unauthorized access", "f": "3"}, {"id": "OT-S05", "c": "S", "t": "Brute-force or password guessing against target", "d": "An attacker could repeatedly try passwords on the target if failed attempts are not limited.", "m": "Limit unsuccessful login attempts (CR 1.11) without blocking essential functions. Obscure authenticator feedback (CR 1.10). Log failed logins. Support MFA for remote / untrusted network access (CR 1.1 RE).", "a": "T0859 Valid Accounts", "r": "4-2 CR 1.11; 4-2 CR 1.10; 4-2 CR 1.7", "p": "Medium", "s": "SL 1", "fr": "FR1 Identification and authentication control", "i": "Unauthorized access", "f": "3"}, {"id": "OT-E11", "c": "E", "t": "Memory corruption or parser flaw in the communication stack of target", "d": "Malformed protocol messages could trigger buffer overflows or parser errors in the target, causing crashes or remote code execution.", "m": "Validate all input (CR 3.5). Use memory-safe languages or compiler hardening. Fuzz-test every protocol interface (4-1 SVV-3) and run communication robustness tests.", "a": "T0866 Exploitation of Remote Services; T0890 Exploitation for Privilege Escalation; T0820 Exploitation for Evasion", "r": "4-2 CR 3.5; 4-1 SI; 4-1 SVV", "p": "High", "s": "SL 1", "fr": "FR3 System integrity", "i": "Full compromise; Loss of availability", "f": "3"}, {"id": "OT-E12", "c": "E", "t": "Insecure default configuration of target", "d": "the target could be deployed with insecure defaults (services enabled, security features off, weak crypto) because secure configuration is not the default or is not documented.", "m": "Ship secure by default. Provide a machine-readable configuration report and the ability to check settings (CR 7.6). Publish hardening and secure integration guidelines (4-1 SG).", "a": "T1694.001 Insecure Credentials: Default Credentials; T0866 Exploitation of Remote Services", "r": "4-2 CR 7.6; 4-2 CR 7.7; 4-1 SG", "p": "Medium", "s": "SL 1", "fr": "FR7 Resource availability", "i": "Attack enablement", "f": "3"}, {"id": "OT-T17", "c": "T", "t": "Vulnerable or compromised third-party component in target", "d": "Open-source or commercial components (RTOS, protocol stacks, libraries) in the target may contain known vulnerabilities or be compromised in the supply chain.", "m": "Maintain an SBOM. Assess third-party components before use (4-1 SM-9, SM-10). Monitor vulnerability sources and handle issues through the defect management process (4-1 DM). Patch or mitigate promptly.", "a": "T0862 Supply Chain Compromise", "r": "4-2 CR 7.8; 4-1 SM-9; 4-1 SM-10; 4-1 DM", "p": "High", "s": "SL 1", "fr": "FR7 Resource availability", "i": "Full compromise", "f": "3"}, {"id": "OT-T18", "c": "T", "t": "Counterfeit device or tampering of target before delivery", "d": "the target could be counterfeited or tampered with during manufacturing, shipping or provisioning, including injection of attacker-controlled keys.", "m": "Provision product-supplier roots of trust in a controlled environment (EDR/NDR 3.12) and let the asset owner provision their own (3.13). Provide device identity certificates and genuineness checks. Use tamper-evident packaging.", "a": "T0862 Supply Chain Compromise", "r": "4-2 EDR 3.12; 4-2 EDR 3.13; 4-1 SM", "p": "Medium", "s": "SL 2", "fr": "FR3 System integrity", "i": "Persistent compromise", "f": "3"}, {"id": "OT-T19", "c": "T", "t": "Security configuration of target disabled or weakened", "d": "An attacker or careless user could turn off logging, authentication or filtering on the target without being noticed.", "m": "Restrict security configuration to administrators. Audit configuration changes (CR 2.8). Support verification of security functions (CR 3.3) and configuration baselines (CR 7.6).", "a": "T0872 Indicator Removal on Host", "r": "4-2 CR 3.3; 4-2 CR 7.6; 4-2 CR 2.8", "p": "Medium", "s": "SL 2", "fr": "FR3 System integrity", "i": "Attack enablement", "f": "3"}, {"id": "OT-D07", "c": "D", "t": "Failed or malicious update leaves target unavailable", "d": "An update to the target could fail, be interrupted or be incompatible, stopping operation with no way back.", "m": "Support atomic update with rollback to the last known-good image. Allow updates to be scheduled by the asset owner without affecting essential functions (EDR/HDR/NDR 3.10). Qualify patches before release (4-1 SUM).", "a": "T0826 Loss of Availability", "r": "4-2 CR 7.4; 4-2 EDR 3.10; 4-2 HDR 3.10; 4-2 NDR 3.10; 4-1 SUM", "p": "Medium", "s": "SL 1", "fr": "FR7 Resource availability", "i": "Loss of availability", "f": "3"}, {"id": "OT-I08", "c": "I", "t": "Weak or obsolete cryptography in target", "d": "the target could use weak algorithms, short keys, poor random numbers or unmanaged certificates, making protections easy to break.", "m": "Use cryptography per recognised standards (CR 4.3). Support crypto agility and certificate lifecycle (CR 1.8, 1.9). Use a hardware RNG where possible.", "a": "T0842 Network Sniffing; T0830 Adversary-in-the-Middle", "r": "4-2 CR 4.3; 4-2 CR 1.8; 4-2 CR 1.9", "p": "Medium", "s": "SL 1", "fr": "FR4 Data confidentiality", "i": "Attack enablement", "f": "3"}, {"id": "OT-E13", "c": "E", "t": "Zone boundary bypass or misconfiguration of target", "d": "Weak rules, any-any rules, protocol tunnelling or misconfiguration on the target could let traffic pass between zones that should be separated.", "m": "Deny by default and allow only documented conduits (NDR 5.2). Use protocol-aware / DPI filtering for industrial protocols. Review rules regularly and alert on changes. Support fail-close behaviour.", "a": "T0884 Connection Proxy; T0886 Remote Services; T0885 Commonly Used Port", "r": "4-2 NDR 5.2; 3-3 SR 5.1; 3-3 SR 5.2", "p": "High", "s": "SL 1", "fr": "FR5 Restricted data flow", "i": "Loss of segmentation", "f": "2"}, {"id": "OT-T20", "c": "T", "t": "Layer 2 attacks via target (VLAN hopping, ARP spoofing, port mirroring)", "d": "An attacker connected to the target could use VLAN hopping, ARP spoofing, rogue DHCP or unauthorised port mirroring to intercept or redirect traffic.", "m": "Enable port security, DHCP snooping, dynamic ARP inspection and disable unused ports. Restrict management access. Log configuration and topology changes.", "a": "T0830 Adversary-in-the-Middle; T0842 Network Sniffing", "r": "4-2 CR 7.6; 4-2 CR 7.7; 4-2 CR 3.1", "p": "Medium", "s": "SL 2", "fr": "FR7 Resource availability", "i": "Manipulation of control; Confidentiality", "f": "2"}, {"id": "OT-D08", "c": "D", "t": "Denial of service of network device target", "d": "Broadcast storms, CAM table overflow, routing / redundancy protocol attacks (MRP, RSTP) or management-plane floods could stop the target from forwarding OT traffic.", "m": "Storm control and rate limiting. Protect the management plane. Authenticate redundancy and routing protocols where supported. Keep forwarding of control traffic independent of management load (CR 7.1).", "a": "T0814 Denial of Service; T0826 Loss of Availability", "r": "4-2 CR 7.1; 4-2 CR 7.2", "p": "Medium", "s": "SL 1", "fr": "FR7 Resource availability", "i": "Loss of availability; Loss of view", "f": "2"}, {"id": "OT-I09", "c": "I", "t": "Management credentials or configuration of target disclosed", "d": "SNMP community strings, Telnet/HTTP management or configuration backups of the target could disclose credentials and network topology.", "m": "Use SNMPv3, SSH and HTTPS for management. Disable Telnet, HTTP and SNMPv1/v2c by default. Encrypt stored configuration backups.", "a": "T0842 Network Sniffing; T0888 Remote System Information Discovery", "r": "4-2 CR 4.1; 4-2 CR 1.5; 4-2 CR 7.7", "p": "Medium", "s": "SL 1", "fr": "FR4 Data confidentiality", "i": "Attack enablement", "f": "2"}, {"id": "OT-S06", "c": "S", "t": "Stolen credentials used for remote access to target", "d": "Phished or reused VPN / remote access credentials could give an attacker interactive access to the target from the Internet.", "m": "Require multi-factor authentication for access from untrusted networks (CR 1.1 RE / SR 1.13). Use individual accounts. Restrict source addresses and time windows.", "a": "T0822 External Remote Services; T0859 Valid Accounts", "r": "3-3 SR 1.13; 4-2 CR 1.1; 4-2 CR 2.6", "p": "High", "s": "SL 2", "fr": "FR1 Identification and authentication control", "i": "Full compromise", "f": "2"}, {"id": "OT-E14", "c": "E", "t": "Unsupervised or persistent third-party access to target", "d": "Vendor or integrator access to the target could be always-on, unsupervised or overly broad, giving a path for attackers who compromise the third party.", "m": "Enable remote access on request only, with approval and session recording. Support remote session termination (CR 2.6) and concurrent session limits (CR 2.7). Restrict third parties to the assets they support.", "a": "T0822 External Remote Services; T0886 Remote Services", "r": "4-2 CR 2.6; 3-3 SR 1.13; 4-2 CR 2.7", "p": "High", "s": "SL 2", "fr": "FR2 Use control", "i": "Full compromise", "f": "5"}, {"id": "OT-E15", "c": "E", "t": "target exposed to the Internet or an untrusted network", "d": "The flow from the source reaches the target over the Internet, cellular or another untrusted network, so it can be found and attacked directly.", "m": "Never expose OT services directly to the Internet. Terminate untrusted connections in a DMZ / remote access gateway with MFA (SR 1.13). Monitor for exposure (e.g. Shodan-type scans of own address space).", "a": "T0883 Internet Accessible Device; T0822 External Remote Services", "r": "3-3 SR 5.2; 3-3 SR 1.13; 4-2 NDR 1.13", "p": "High", "s": "SL 1", "fr": "FR5 Restricted data flow", "i": "Full compromise", "f": "1"}, {"id": "OT-I10", "c": "I", "t": "Wireless sniffing of traffic to target", "d": "Radio traffic to the target can be captured from outside the physical perimeter.", "m": "Use strong wireless security (WPA3-Enterprise, WirelessHART/ISA100 join keys managed securely). Control wireless use (CR 2.2, SR 1.6). Add application-level encryption for sensitive data.", "a": "T0887 Wireless Sniffing", "r": "4-2 CR 4.1; 4-2 CR 2.2; 3-3 SR 1.6", "p": "Medium", "s": "SL 1", "fr": "FR4 Data confidentiality", "i": "Confidentiality; Attack enablement", "f": "1"}, {"id": "OT-S07", "c": "S", "t": "Rogue access point or rogue wireless device connecting to target", "d": "An attacker could set up a rogue AP or join a rogue device to the wireless network used by the target.", "m": "Mutual authentication of wireless devices and networks (SR 1.6). Wireless intrusion detection. Disable unused radios (CR 7.7).", "a": "T0860 Wireless Compromise; T0848 Rogue Master", "r": "3-3 SR 1.6; 4-2 CR 2.2; 4-2 CR 1.2; 4-2 CR 1.6", "p": "High", "s": "SL 2", "fr": "FR1 Identification and authentication control", "i": "Manipulation of control", "f": "2"}, {"id": "OT-D09", "c": "D", "t": "RF jamming or de-authentication of target", "d": "Radio jamming or de-authentication attacks could cut wireless communication to the target.", "m": "Do not use wireless for safety-critical or time-critical control without a fail-safe on loss of communication. Use protected management frames (802.11w). Monitor link quality.", "a": "T0814 Denial of Service; T0860 Wireless Compromise", "r": "4-2 CR 7.1; 4-2 CR 3.6", "p": "Medium", "s": "SL 1", "fr": "FR7 Resource availability", "i": "Loss of control; Loss of view", "f": "1"}, {"id": "OT-T21", "c": "T", "t": "Compromised update channel between source and target", "d": "The update server, repository or delivery path could be compromised to distribute malicious firmware or software.", "m": "Sign all update packages with keys protected in an HSM. Verify signature and version on the target. Protect the build and release pipeline (4-1 SM-7/SM-8). Publish hashes and security update notifications (4-1 SUM).", "a": "T0862 Supply Chain Compromise; T1693.001 Modify Firmware: System Firmware", "r": "4-2 CR 3.4; 4-2 EDR 3.10; 4-1 SUM; 4-1 SM", "p": "High", "s": "SL 1", "fr": "FR3 System integrity", "i": "Fleet-wide compromise", "f": "5"}, {"id": "OT-T22", "c": "T", "t": "Malware introduced into target via removable media or transient device", "d": "USB drives, SD cards or maintenance laptops connected to the target could carry malware (e.g. Stuxnet).", "m": "Disable autorun. Restrict or disable USB ports (CR 7.7). Scan media at a kiosk before use. Accept only signed files. Control portable and mobile devices (SR 2.3).", "a": "T0847 Replication Through Removable Media; T0864 Transient Cyber Asset; T0895 Autorun Image", "r": "4-2 EDR 3.2; 4-2 HDR 3.2; 4-2 CR 7.7; 3-3 SR 2.3", "p": "High", "s": "SL 1", "fr": "FR3 System integrity", "i": "Full compromise", "f": "5"}, {"id": "OT-T23", "c": "T", "t": "Tampering with control-critical data in target", "d": "Logic, configuration, setpoints or recipes in the target could be modified, so the process runs with wrong or unsafe settings.", "m": "Integrity-protect stored data (CR 3.4) with signatures or hashes checked before use. Restrict write access. Keep version history and change approvals.", "a": "T0836 Modify Parameter; T0889 Modify Program", "r": "4-2 CR 3.4; 4-2 CR 2.1", "p": "High", "s": "SL 1", "fr": "FR3 System integrity", "i": "Safety; Product quality; Loss of control", "f": "8"}, {"id": "OT-T23R", "c": "T", "t": "Tampering with control-critical data in source", "d": "Logic, configuration, setpoints or recipes in the source could be modified, so the process runs with wrong or unsafe settings.", "m": "Integrity-protect stored data (CR 3.4) with signatures or hashes checked before use. Restrict write access. Keep version history and change approvals.", "a": "T0836 Modify Parameter; T0889 Modify Program", "r": "4-2 CR 3.4; 4-2 CR 2.1", "p": "High", "s": "SL 1", "fr": "FR3 System integrity", "i": "Safety; Product quality; Loss of control", "f": "8s"}, {"id": "OT-T24", "c": "T", "t": "Tampering with firmware images in target", "d": "Firmware or software images stored in the target could be replaced with malicious versions before they are installed.", "m": "Store only signed images and verify signatures at install and boot (CR 3.4, EDR 3.14). Restrict write access to the repository.", "a": "T1693.001 Modify Firmware: System Firmware; T0862 Supply Chain Compromise", "r": "4-2 CR 3.4; 4-2 EDR 3.14", "p": "High", "s": "SL 1", "fr": "FR3 System integrity", "i": "Persistent compromise", "f": "8"}, {"id": "OT-T24R", "c": "T", "t": "Tampering with firmware images in source", "d": "Firmware or software images stored in the source could be replaced with malicious versions before they are installed.", "m": "Store only signed images and verify signatures at install and boot (CR 3.4, EDR 3.14). Restrict write access to the repository.", "a": "T1693.001 Modify Firmware: System Firmware; T0862 Supply Chain Compromise", "r": "4-2 CR 3.4; 4-2 EDR 3.14", "p": "High", "s": "SL 1", "fr": "FR3 System integrity", "i": "Persistent compromise", "f": "8s"}, {"id": "OT-I11", "c": "I", "t": "Disclosure of credentials or keys from target", "d": "Secrets in the target could be read by an unauthorised process or user, enabling impersonation and decryption.", "m": "Store secrets hashed (passwords) or in hardware-protected storage (keys). Restrict access to the owning process. Encrypt at rest (CR 4.1).", "a": "T1694.002 Insecure Credentials: Hardcoded Credentials; T0859 Valid Accounts", "r": "4-2 CR 4.1; 4-2 CR 1.5; 4-2 CR 4.3", "p": "High", "s": "SL 1", "fr": "FR4 Data confidentiality", "i": "Unauthorized access; Fleet-wide compromise", "f": "8"}, {"id": "OT-I11R", "c": "I", "t": "Disclosure of credentials or keys from source", "d": "Secrets in the source could be read by an unauthorised process or user, enabling impersonation and decryption.", "m": "Store secrets hashed (passwords) or in hardware-protected storage (keys). Restrict access to the owning process. Encrypt at rest (CR 4.1).", "a": "T1694.002 Insecure Credentials: Hardcoded Credentials; T0859 Valid Accounts", "r": "4-2 CR 4.1; 4-2 CR 1.5; 4-2 CR 4.3", "p": "High", "s": "SL 1", "fr": "FR4 Data confidentiality", "i": "Unauthorized access; Fleet-wide compromise", "f": "8s"}, {"id": "OT-I12", "c": "I", "t": "Sensitive data in target recoverable after decommissioning", "d": "Data in the target could remain readable after the component is replaced, repaired or scrapped.", "m": "Support secure erase of all sensitive information (CR 4.2) and document decommissioning in the security guidelines.", "a": "T0893 Data from Local System", "r": "4-2 CR 4.2; 4-1 SG", "p": "Low", "s": "SL 2", "fr": "FR4 Data confidentiality", "i": "Confidentiality / IP", "f": "8"}, {"id": "OT-I12R", "c": "I", "t": "Sensitive data in source recoverable after decommissioning", "d": "Data in the source could remain readable after the component is replaced, repaired or scrapped.", "m": "Support secure erase of all sensitive information (CR 4.2) and document decommissioning in the security guidelines.", "a": "T0893 Data from Local System", "r": "4-2 CR 4.2; 4-1 SG", "p": "Low", "s": "SL 2", "fr": "FR4 Data confidentiality", "i": "Confidentiality / IP", "f": "8s"}, {"id": "OT-R03", "c": "R", "t": "Audit records in target modified or deleted", "d": "An attacker could delete or alter audit records in the target to hide their actions.", "m": "Protect audit information against unauthorised access, modification and deletion (CR 3.9). Forward logs in near real time to a central collector (CR 6.1).", "a": "T0872 Indicator Removal on Host", "r": "4-2 CR 3.9; 4-2 CR 6.1", "p": "High", "s": "SL 2", "fr": "FR3 System integrity", "i": "Forensics", "f": "8"}, {"id": "OT-R03R", "c": "R", "t": "Audit records in source modified or deleted", "d": "An attacker could delete or alter audit records in the source to hide their actions.", "m": "Protect audit information against unauthorised access, modification and deletion (CR 3.9). Forward logs in near real time to a central collector (CR 6.1).", "a": "T0872 Indicator Removal on Host", "r": "4-2 CR 3.9; 4-2 CR 6.1", "p": "High", "s": "SL 2", "fr": "FR3 System integrity", "i": "Forensics", "f": "8s"}, {"id": "OT-D10", "c": "D", "t": "Audit storage of target exhausted", "d": "An attacker could flood the target with events to fill storage, overwriting evidence or stopping logging.", "m": "Allocate sufficient audit storage and warn before it is full (CR 2.9). Define behaviour on audit failure without losing essential functions (CR 2.10).", "a": "T0872 Indicator Removal on Host", "r": "4-2 CR 2.9; 4-2 CR 2.10", "p": "Medium", "s": "SL 1", "fr": "FR2 Use control", "i": "Forensics", "f": "8"}, {"id": "OT-D10R", "c": "D", "t": "Audit storage of source exhausted", "d": "An attacker could flood the source with events to fill storage, overwriting evidence or stopping logging.", "m": "Allocate sufficient audit storage and warn before it is full (CR 2.9). Define behaviour on audit failure without losing essential functions (CR 2.10).", "a": "T0872 Indicator Removal on Host", "r": "4-2 CR 2.9; 4-2 CR 2.10", "p": "Medium", "s": "SL 1", "fr": "FR2 Use control", "i": "Forensics", "f": "8s"}, {"id": "OT-D11", "c": "D", "t": "Backups in target unavailable, encrypted or corrupted", "d": "Backups could be encrypted by ransomware, deleted or silently corrupted, preventing recovery of the control system.", "m": "Support backup without affecting operations (CR 7.3) with integrity verification. Keep offline / immutable copies. Test restore regularly (CR 7.4).", "a": "T0809 Data Destruction", "r": "4-2 CR 7.3; 4-2 CR 7.4", "p": "High", "s": "SL 1", "fr": "FR7 Resource availability", "i": "Loss of production; Recovery time", "f": "8"}, {"id": "OT-D11R", "c": "D", "t": "Backups in source unavailable, encrypted or corrupted", "d": "Backups could be encrypted by ransomware, deleted or silently corrupted, preventing recovery of the control system.", "m": "Support backup without affecting operations (CR 7.3) with integrity verification. Keep offline / immutable copies. Test restore regularly (CR 7.4).", "a": "T0809 Data Destruction", "r": "4-2 CR 7.3; 4-2 CR 7.4", "p": "High", "s": "SL 1", "fr": "FR7 Resource availability", "i": "Loss of production; Recovery time", "f": "8s"}, {"id": "OT-I13", "c": "I", "t": "Bulk exfiltration of data from target", "d": "Historical process data, backups or projects in the target could be copied out in bulk to the enterprise or Internet.", "m": "Encrypt at rest (CR 4.1). Restrict read access. Use one-way replication (e.g. data diode) to the enterprise. Monitor for unusual volumes.", "a": "T0811 Data from Information Repositories; T0882 Theft of Operational Information", "r": "4-2 CR 4.1; 3-3 SR 5.1", "p": "Medium", "s": "SL 2", "fr": "FR4 Data confidentiality", "i": "Confidentiality / IP", "f": "8"}, {"id": "OT-I13R", "c": "I", "t": "Bulk exfiltration of data from source", "d": "Historical process data, backups or projects in the source could be copied out in bulk to the enterprise or Internet.", "m": "Encrypt at rest (CR 4.1). Restrict read access. Use one-way replication (e.g. data diode) to the enterprise. Monitor for unusual volumes.", "a": "T0811 Data from Information Repositories; T0882 Theft of Operational Information", "r": "4-2 CR 4.1; 3-3 SR 5.1", "p": "Medium", "s": "SL 2", "fr": "FR4 Data confidentiality", "i": "Confidentiality / IP", "f": "8s"}, {"id": "OT-S08", "c": "S", "t": "Impersonation of source at target", "d": "An attacker could impersonate the source at the target using stolen, guessed or shared credentials.", "m": "Authenticate all human users (CR 1.1). Strong password policy (CR 1.7). MFA for privileged and remote users. Integrate with central account management (CR 1.3).", "a": "T0859 Valid Accounts", "r": "4-2 CR 1.1; 4-2 CR 1.3; 4-2 CR 1.7", "p": "High", "s": "SL 1", "fr": "FR1 Identification and authentication control", "i": "Unauthorized access", "f": "5"}, {"id": "OT-E16", "c": "E", "t": "Insider misuse of privileged access by source on target", "d": "A malicious or coerced the source could misuse legitimate privileges on the target.", "m": "Least privilege and separation of duties (CR 2.1). Dual control for critical changes. Audit privileged actions and review them (CR 2.8).", "a": "T0859 Valid Accounts", "r": "4-2 CR 2.1; 4-2 CR 2.8; 4-2 CR 1.3", "p": "Medium", "s": "SL 2", "fr": "FR2 Use control", "i": "Loss of control; Safety", "f": "5"}, {"id": "OT-E17", "c": "E", "t": "Pivot from enterprise IT (source) into target", "d": "An attacker who compromised the source could use this flow to move laterally into the OT environment.", "m": "Terminate IT-to-OT flows in an industrial DMZ. No direct connections from IT to Level 1/2. Use separate identities for IT and OT. Allow only specific, documented services through the conduit.", "a": "T0866 Exploitation of Remote Services; T0886 Remote Services; T0884 Connection Proxy", "r": "3-3 SR 5.1; 3-3 SR 5.2; 4-2 NDR 5.2", "p": "High", "s": "SL 1", "fr": "FR5 Restricted data flow", "i": "Full compromise", "f": "5"}, {"id": "OT-E18", "c": "E", "t": "Direct connection from source to controller target", "d": "the target receives traffic directly from the enterprise or cloud, bypassing the zone model.", "m": "Route through an edge gateway / DMZ that terminates the connection. Make controller access from higher levels read-only or brokered. Re-assess the zone and conduit design.", "a": "T0883 Internet Accessible Device; T0886 Remote Services", "r": "3-3 SR 5.1; 3-3 SR 5.2; 3-2 ZCR 3", "p": "High", "s": "SL 1", "fr": "FR5 Restricted data flow", "i": "Loss of control", "f": "5"}, {"id": "OT-T25", "c": "T", "t": "Cloud-originated commands or configuration to target", "d": "If the cloud platform is compromised, it could push malicious commands, configuration or apps to the target.", "m": "Keep cloud-to-OT flows read-only where possible. Require local approval for write operations. Authenticate the cloud endpoint and sign commands. Apply allow-lists for permitted operations.", "a": "T1692.001 Unauthorized Message: Command Message; T0869 Standard Application Layer Protocol", "r": "3-3 SR 5.2; 4-2 CR 2.1; 4-2 CR 3.1", "p": "High", "s": "SL 2", "fr": "FR5 Restricted data flow", "i": "Loss of control", "f": "5"}, {"id": "OT-I14", "c": "I", "t": "Operational data exposed in vendor / cloud service target", "d": "Telemetry and operational data sent to the target could be exposed through cloud misconfiguration or vendor compromise.", "m": "Encrypt in transit and at rest. Minimise data sent. Define data ownership, retention and access in contracts. Assess the cloud provider (4-1 SM).", "a": "T0882 Theft of Operational Information", "r": "4-2 CR 4.1; 4-1 SM", "p": "Medium", "s": "SL 1", "fr": "FR4 Data confidentiality", "i": "Confidentiality / IP", "f": "2"}, {"id": "OT-S09", "c": "S", "t": "Time source spoofing affecting target", "d": "Spoofed NTP, PTP or GNSS time could corrupt timestamps on the target, break certificate validation or disturb sequence-of-events and protection functions.", "m": "Authenticate time sources (NTS, PTP security, multiple sources). Detect time jumps. Protect timestamp integrity (CR 2.11).", "a": "T0849 Masquerading; T0830 Adversary-in-the-Middle", "r": "4-2 CR 2.11; 3-3 SR 2.11", "p": "Medium", "s": "SL 2", "fr": "FR2 Use control", "i": "Forensics; Protection mis-operation", "f": "1"}, {"id": "OT-S10", "c": "S", "t": "Certificate or PKI misuse affecting target", "d": "Mis-issued, unrevoked or self-signed certificates could let an attacker impersonate components; an unavailable PKI could stop authentication.", "m": "Validate certificate chains, revocation and validity (CR 1.8). Support asset-owner PKI and offline operation. Define certificate lifecycle in the security guidelines.", "a": "T0849 Masquerading", "r": "4-2 CR 1.8; 4-2 CR 1.9; 4-2 EDR 3.13", "p": "Medium", "s": "SL 2", "fr": "FR1 Identification and authentication control", "i": "Unauthorized access", "f": "5"}, {"id": "OT-T26", "c": "T", "t": "Physical inputs to target manipulated at the process", "d": "Someone could manipulate sensors or the process physically (bypass a sensor, inject a signal), so the target acts on false inputs.", "m": "Apply plausibility checks and redundancy for critical measurements (CR 3.5). Physically protect critical sensors. Use independent safety instrumentation.", "a": "T1692.002 Unauthorized Message: Reporting Message; T0831 Manipulation of Control", "r": "4-2 CR 3.5; 4-2 CR 3.6", "p": "Medium", "s": "SL 2", "fr": "FR3 System integrity", "i": "Safety; Product quality", "f": "5"}, {"id": "OT-E19", "c": "E", "t": "Container escape or app isolation failure on target", "d": "A malicious or vulnerable app on the target could break out of its container or access other apps' data and OT interfaces.", "m": "Run apps with least privilege, no privileged containers, read-only filesystems and resource limits. Sign and vet apps. Partition applications (SR 5.4).", "a": "T0890 Exploitation for Privilege Escalation", "r": "3-3 SR 5.4; 4-2 CR 2.1; 4-2 CR 7.2", "p": "High", "s": "SL 2", "fr": "FR5 Restricted data flow", "i": "Full compromise", "f": "2"}, {"id": "OT-E20", "c": "E", "t": "target bridges insecure legacy traffic into a secured network", "d": "the target may translate unauthenticated legacy protocols (Modbus, OPC DA) into OPC UA or other networks, so attacks on the legacy side are passed through.", "m": "Place the gateway at a zone boundary. Expose only required tags with read-only access by default. Validate values before forwarding. Authenticate clients on the secure side.", "a": "T0884 Connection Proxy; T1692.001 Unauthorized Message: Command Message", "r": "3-3 SR 5.2; 4-2 CR 3.5; 4-2 CR 2.1", "p": "Medium", "s": "SL 2", "fr": "FR5 Restricted data flow", "i": "Manipulation of control", "f": "5"}, {"id": "OT-S11", "c": "S", "t": "OPC UA trust misconfiguration on target", "d": "Auto-accepting client certificates, security mode None or anonymous access on the target would let any client connect and read or write.", "m": "Disable security mode None and anonymous access by default. Require explicit trust of client certificates. Map users to roles.", "a": "T0849 Masquerading; T0859 Valid Accounts", "r": "4-2 CR 1.2; 4-2 CR 1.8; 4-2 CR 2.1", "p": "Medium", "s": "SL 1", "fr": "FR1 Identification and authentication control", "i": "Unauthorized access", "f": "5"}, {"id": "OT-E21", "c": "E", "t": "Compromise of identity service target gives access to all OT assets", "d": "If the directory / identity service is compromised (or shared with IT), the attacker can create or use accounts on every connected OT component.", "m": "Use a dedicated OT identity domain separate from IT. Tier administrative accounts. Monitor privileged account changes.", "a": "T0859 Valid Accounts; T0892 Change Credential", "r": "4-2 CR 1.3; 4-2 CR 1.1; 3-3 SR 1.3", "p": "High", "s": "SL 2", "fr": "FR1 Identification and authentication control", "i": "Full compromise", "f": "2"}, {"id": "OT-D12", "c": "D", "t": "Identity service unavailable blocks operators on target", "d": "If the identity service is unreachable, operators may be locked out of the target during an incident or emergency.", "m": "Support local fallback / emergency accounts with strong controls. Do not let security functions block essential functions (IEC 62443-4-2 essential functions).", "a": "T0826 Loss of Availability; T0815 Denial of View", "r": "4-2 CR 7.1 (essential functions); 4-2 CR 1.11", "p": "Medium", "s": "SL 1", "fr": "FR7 Resource availability", "i": "Loss of view; Loss of control", "f": "5"}, {"id": "OT-R04", "c": "R", "t": "Security events from source do not reach target", "d": "Events may be dropped, delayed or blocked, so attacks against the source go undetected.", "m": "Support continuous monitoring (CR 6.2) and standard log export (syslog/CEF) (CR 6.1). Use reliable transport and alert on missing heartbeats.", "a": "T0872 Indicator Removal on Host", "r": "4-2 CR 6.1; 4-2 CR 6.2", "p": "Medium", "s": "SL 2", "fr": "FR6 Timely response to events", "i": "Detection", "f": "5"}, {"id": "OT-D13", "c": "D", "t": "Active scanning by source disrupts target", "d": "Active discovery or vulnerability scanning of the target could crash or slow fragile embedded devices.", "m": "Prefer passive monitoring for Level 0-2. Test and document safe active queries. Make {target.Name} robust to scanning traffic (CR 7.1).", "a": "T0814 Denial of Service", "r": "4-2 CR 7.1; 4-2 CR 6.2", "p": "Medium", "s": "SL 1", "fr": "FR7 Resource availability", "i": "Loss of availability", "f": "5"}, {"id": "OT-T27", "c": "T", "t": "Mass configuration change through target", "d": "Device management platform the target can push configuration, firmware or certificates to many devices; if compromised, the whole fleet is affected.", "m": "Strong authentication and role separation for fleet operations. Staged roll-out with approval. Signed configuration packages. Audit all bulk operations.", "a": "T1693.002 Modify Firmware: Module Firmware; T0836 Modify Parameter", "r": "4-2 CR 2.1; 4-2 CR 3.4; 4-2 CR 2.8", "p": "Medium", "s": "SL 2", "fr": "FR2 Use control", "i": "Fleet-wide compromise", "f": "2"}, {"id": "OT-R05", "c": "R", "t": "Logic or configuration changes on target cannot be proven or reconstructed", "d": "Program downloads, online edits and parameter changes made on the target by the source may not be recorded with who made them, what changed and when. After an incident it cannot be shown whether a change was authorised, accidental or malicious.", "m": "Record every logic, configuration and firmware change with user identity, timestamp and a before/after hash or version (CR 2.8). Keep a change history on the device or engineering server. Support non-repudiation for critical changes at SL 3 and above (CR 2.12). Compare running logic with the approved baseline.", "a": "T0889 Modify Program; T0843 Program Download; T0872 Indicator Removal on Host", "r": "4-2 CR 2.12; 4-2 CR 2.8; 4-2 CR 3.4", "p": "Medium", "s": "SL 2", "fr": "FR2 Use control", "i": "Forensics; Compliance; Safety case", "f": "5"}, {"id": "OT-R06", "c": "R", "t": "Local audit trail on target lost, overwritten or cleared", "d": "Embedded and network devices often keep only a small local event buffer. An attacker could clear it, flood it until older events are overwritten, or reboot the target so evidence held in volatile memory is lost.", "m": "Protect audit records against deletion (CR 3.9) and keep them across restarts. Forward events in near real time to a central collector (CR 6.1, syslog over TLS). Warn when audit capacity is nearly used (CR 2.9). Record clearing of the log as an audit event itself.", "a": "T0872 Indicator Removal on Host; T0816 Device Restart/Shutdown", "r": "4-2 CR 3.9; 4-2 CR 2.9; 4-2 CR 6.1", "p": "Medium", "s": "SL 2", "fr": "FR3 System integrity", "i": "Forensics; Detection", "f": "3"}, {"id": "OT-R07", "c": "R", "t": "Operator actions by source on target not journaled", "d": "Commands, setpoint changes, alarm acknowledgements and shelving done by the source on the target may not be recorded with user, old and new value and time, so a disputed or harmful operation cannot be reconstructed.", "m": "Keep an operator action journal with user identity, old/new value, source station and synchronised time (CR 2.8, CR 2.11). Protect the journal from modification (CR 3.9). Make it available to incident response and the historian.", "a": "T0872 Indicator Removal on Host; T1692.001 Unauthorized Message: Command Message", "r": "4-2 CR 2.8; 4-2 CR 2.11; 4-2 CR 2.12; 4-2 CR 3.9", "p": "Medium", "s": "SL 1", "fr": "FR2 Use control", "i": "Forensics; Compliance", "f": "5"}, {"id": "OT-D14", "c": "D", "t": "Command, trip or alarm messages between source and target blocked", "d": "An attacker on the path, or on a device in between, could selectively drop or delay commands, trips, alarms or status messages between the source and the target while the link still looks healthy, so a response to a process upset never arrives.", "m": "Use communication watchdogs, heartbeats and sequence counters so that missing or late messages are detected (CR 3.1, CR 7.1). Define the safe state on loss of communication (CR 3.6). Alarm on communication loss to the operator. Use redundant paths for essential functions and keep safety trips independent of the control network.", "a": "T1691.001 Block Operational Technology Message: Command Message; T1691.002 Block Operational Technology Message: Reporting Message; T1695.002 Block Communications: Ethernet; T1695.001 Block Communications: Serial COM; T0827 Loss of Control", "r": "4-2 CR 7.1; 4-2 CR 3.6; 4-2 CR 3.1", "p": "High", "s": "SL 2", "fr": "FR7 Resource availability", "i": "Loss of control; Safety; Damage to property", "f": "1"}, {"id": "OT-I15", "c": "I", "t": "Process state and I/O image read from target by an unauthorised client", "d": "the target answers read requests over an unauthenticated protocol, so any host that can reach it could poll tags, I/O image and operating state to learn how the process works before an attack.", "m": "Require authentication and authorisation for read services as well as writes where the protocol allows (CR 2.1). Allow-list client addresses. Expose only required tags. Detect unexpected polling clients at the conduit or with network monitoring (CR 6.2).", "a": "T0801 Monitor Process State; T0877 I/O Image; T0861 Point & Tag Identification; T0802 Automated Collection", "r": "4-2 CR 2.1; 4-2 CR 4.1; 4-2 CR 6.2", "p": "Medium", "s": "SL 2", "fr": "FR2 Use control", "i": "Attack enablement; Confidentiality / IP", "f": "1"}, {"id": "OT-E22", "c": "E", "t": "Attacker tools staged on target to reach the control network", "d": "the target has network access to controllers. An attacker who gets code onto it (drive-by download, script, phishing, lateral transfer from another host) could use built-in tools, scripts or API hooking to scan, move laterally and send commands as a trusted host.", "m": "Use application allow-listing and block script interpreters that are not needed (HDR 3.2, SAR 2.4). Do not allow web browsing or e-mail on OT hosts (CR 5.3 person-to-person communication). Restrict outbound and lateral connections from the host. Monitor for new executables and tools.", "a": "T0867 Lateral Tool Transfer; T0817 Drive-by Compromise; T0874 Hooking; T1701.001 Command and Scripting Interpreter: PowerShell; T0852 Screen Capture; T0840 Network Connection Enumeration", "r": "4-2 HDR 3.2; 4-2 SAR 2.4; 4-2 CR 7.7; 4-2 CR 5.1", "p": "High", "s": "SL 2", "fr": "FR3 System integrity", "i": "Full compromise; Loss of control", "f": "4"}, {"id": "OT-T29", "c": "T", "t": "Rogue publisher or subscriber on the source to target messaging channel", "d": "On publish/subscribe channels (MQTT, cloud messaging) any client the broker accepts may publish to or subscribe to topics. A rogue client could inject false values or commands for the target, or read all telemetry.", "m": "Require client authentication (certificates) on the broker and per-topic access control lists (CR 1.2, CR 2.1). Use TLS. Sign or validate payloads that carry commands. Disable wildcard subscriptions for untrusted clients.", "a": "T0869.002 Standard Application Layer Protocol: Publish/Subscribe Protocols; T1692.001 Unauthorized Message: Command Message; T1692.002 Unauthorized Message: Reporting Message", "r": "4-2 CR 1.2; 4-2 CR 2.1; 4-2 CR 3.1", "p": "High", "s": "SL 2", "fr": "FR1 Identification and authentication control", "i": "Manipulation of control; Manipulation of view", "f": "1"}, {"id": "OT-T28", "c": "T", "t": "Malicious code inserted into target during development or build", "d": "A compromised developer account, source repository, build server or dependency could insert a backdoor into the target before it is signed and released, so every shipped unit carries it (e.g. SolarWinds-type attacks).", "m": "Protect the development environment and build pipeline (4-1 SM-7, SM-8): access control and MFA for repositories, protected branches, reviewed changes, reproducible builds and an isolated build server. Scan dependencies and keep an SBOM. Sign release artefacts only from the controlled pipeline.", "a": "T0862 Supply Chain Compromise", "r": "4-2 CR 3.4; 4-1 SM-7; 4-1 SM-8; 4-1 SI", "p": "High", "s": "SL 1", "fr": "FR3 System integrity", "i": "Fleet-wide compromise", "f": "6"}, {"id": "OT-S12", "c": "S", "t": "Code-signing key for software delivered via target stolen or misused", "d": "If the supplier's firmware or software signing key is stolen, or the signing service can be used by an unauthorised person, malicious images would pass every signature check on the devices that the target serves.", "m": "Keep signing keys in an HSM with dual control and logging (4-1 SM-8). Use separate keys for test and production. Plan key revocation and rotation, and let devices accept a new trust anchor securely (CR 1.9, EDR 3.10). Monitor signing activity.", "a": "T0862 Supply Chain Compromise; T1693.001 Modify Firmware: System Firmware", "r": "4-2 CR 1.9; 4-2 CR 3.4; 4-2 EDR 3.10; 4-1 SM-8", "p": "High", "s": "SL 2", "fr": "FR1 Identification and authentication control", "i": "Fleet-wide compromise", "f": "6"}, {"id": "OT-S13", "c": "S", "t": "Dormant, orphaned or unrevoked accounts on target", "d": "Accounts of former staff, contractors, commissioning engineers or test users may remain active on the target and can be used by an attacker who obtains their credentials.", "m": "Support account management functions: create, modify, disable and remove accounts, with expiry dates (CR 1.3, CR 1.4). Report inactive accounts. Integrate with central identity management so leavers are removed everywhere. Remove test and commissioning accounts before handover.", "a": "T0859 Valid Accounts; T1694.001 Insecure Credentials: Default Credentials", "r": "4-2 CR 1.4; 4-2 CR 1.3; 4-2 CR 1.5", "p": "Medium", "s": "SL 1", "fr": "FR1 Identification and authentication control", "i": "Unauthorized access", "f": "3"}, {"id": "OT-E23", "c": "E", "t": "Isolation between source and target bypassed", "d": "the source and the target run in separate privilege or isolation domains (container, process, kernel and user space, safety partition). A flaw or misconfiguration in the isolation could let code in the source act with the rights of the target.", "m": "Run each function with least privilege and in its own isolation domain (CR 2.1). Restrict the interface between the domains to the calls that are needed and validate everything that crosses it (CR 3.5). Keep the isolation mechanism (container runtime, hypervisor, OS) patched and hardened, and test it in penetration tests.", "a": "T0890 Exploitation for Privilege Escalation", "r": "4-2 CR 2.1; 4-2 CR 3.5; 4-2 CR 5.1", "p": "Medium", "s": "SL 2", "fr": "FR2 Use control", "i": "Privilege escalation; Loss of control", "f": "7"}, {"id": "OT-T30", "c": "T", "t": "Signals between source and target injected, cut or bridged at the wiring", "d": "The signal from the source to the target is carried on wiring or a local interface that a person with physical access can reach. Injecting, cutting or bridging it can change the process or defeat a safety function without any network access.", "m": "Protect wiring and terminals in locked cabinets and enclosures with intrusion detection (EDR 3.11). Design safety-relevant inputs fail-safe and monitored (wire-break and short-circuit detection). Detect implausible signal changes in the logic.", "a": "T0831 Manipulation of Control; T0880 Loss of Safety", "r": "4-2 EDR 3.11; 4-2 CR 3.1", "p": "Medium", "s": "SL 2", "fr": "FR3 System integrity", "i": "Manipulation of control; Safety", "f": "7"}], "plant": [{"id": "PL-E01", "c": "E", "t": "source to target crosses a zone boundary without a conduit device", "d": "The flow from the source to the target crosses a zone boundary but is not filtered by a firewall or conduit device, so the zones are not really separated and an attacker in one zone can reach the other freely.", "m": "Route every inter-zone flow through a conduit device (firewall, data diode, DPI gateway) with deny-by-default rules that allow only this documented flow. Record the conduit in the zone and conduit drawing.", "a": "T0886 Remote Services; T0866 Exploitation of Remote Services", "r": "3-3 SR 5.1; 3-3 SR 5.2; 3-2 ZCR 3; 2-1 NET 1", "p": "High", "s": "SL 1", "fr": "FR5 Restricted data flow", "i": "Loss of segmentation; Attack spread", "f": "1"}, {"id": "PL-T01", "c": "T", "t": "Unauthenticated control traffic from source to target crosses zones", "d": "Commands or setpoints sent to the target use a protocol without authentication across a zone boundary. Anyone who gets a foothold on the path or in the source zone can send valid-looking commands.", "m": "Allow only the specific function codes or services needed at the conduit (protocol-aware firewall). Restrict which hosts may send writes. Use secure protocol variants where the installed equipment supports them. Monitor for writes from unexpected hosts.", "a": "T1692.001 Unauthorized Message: Command Message; T0831 Manipulation of Control", "r": "3-3 SR 3.1; 3-3 SR 5.2; 2-1 NET 1", "p": "High", "s": "SL 2", "fr": "FR3 System integrity", "i": "Manipulation of control; Safety; Production loss", "f": "1"}, {"id": "PL-I01", "c": "I", "t": "Plant data between source and target readable in transit", "d": "Traffic between the source and the target is not encrypted where it leaves the zone. Process data, tag names or credentials can be captured and used to plan an attack.", "m": "Encrypt flows leaving the zone where confidentiality matters (TLS, IPsec tunnel between sites). Never send passwords in cleartext. Classify plant data to decide where encryption is needed.", "a": "T0842 Network Sniffing; T0882 Theft of Operational Information", "r": "3-3 SR 4.1; 2-1 DATA 1", "p": "Medium", "s": "SL 2", "fr": "FR4 Data confidentiality", "i": "Confidentiality; Attack enablement", "f": "1"}, {"id": "PL-E02", "c": "E", "t": "Attack path from the business network via source to target", "d": "the source is on the business network, which is far more exposed to phishing and ransomware. This flow is a path from a compromised office PC or server into the plant.", "m": "Terminate business-to-plant flows in the industrial DMZ. Do not allow business hosts to connect to Level 1 and 2 directly. Use separate accounts and domains for IT and OT. Review this flow in the conduit rule set.", "a": "T0886 Remote Services; T0884 Connection Proxy; T0866 Exploitation of Remote Services", "r": "3-3 SR 5.1; 3-3 SR 5.2; 2-1 NET 1", "p": "High", "s": "SL 1", "fr": "FR5 Restricted data flow", "i": "Production loss; Ransomware spread", "f": "5"}, {"id": "PL-E03", "c": "E", "t": "Controller target reachable from outside the plant", "d": "the target receives traffic directly from the business network, a cloud service or an untrusted network, bypassing the supervisory and DMZ layers.", "m": "Broker the connection through the DMZ or a remote access gateway. Make any access from higher levels read-only. Re-check the zone model and the SL-T for this zone.", "a": "T0883 Internet Accessible Device; T0886 Remote Services", "r": "3-3 SR 5.1; 3-3 SR 5.2; 3-2 ZCR 3", "p": "High", "s": "SL 1", "fr": "FR5 Restricted data flow", "i": "Loss of control; Safety", "f": "5"}, {"id": "PL-I02", "c": "I", "t": "target discoverable from the Internet or a carrier network", "d": "the target is reached over the Internet or a cellular or WAN carrier network. Exposed industrial services are routinely found by Internet-wide scanning and attacked within days.", "m": "Use a private APN or VPN for cellular links. Block inbound connections from the Internet. Check your public address ranges regularly for exposed OT services.", "a": "T0883 Internet Accessible Device; T0846 Remote System Discovery", "r": "3-3 SR 5.2; 3-3 SR 1.13; 2-1 NET 3", "p": "High", "s": "SL 1", "fr": "FR5 Restricted data flow", "i": "Attack enablement; Loss of control", "f": "1"}, {"id": "PL-D01", "c": "D", "t": "Carrier or WAN outage cuts source from target", "d": "The link between the source and the target depends on an external carrier or WAN. An outage, a jamming attack or an attack on the provider stops remote control and monitoring.", "m": "Define how the remote site behaves on loss of communication (local autonomous control, safe state). Provide a backup path for essential sites. Include the carrier in incident and continuity plans.", "a": "T1695.002 Block Communications: Ethernet; T0827 Loss of Control", "r": "3-3 SR 7.1; 2-1 AVAIL 1", "p": "Medium", "s": "SL 1", "fr": "FR7 Resource availability", "i": "Loss of view; Loss of control", "f": "1"}, {"id": "PL-E04", "c": "E", "t": "Unmanaged or undocumented WAN or cellular connection at target", "d": "Cellular routers and WAN links are often installed by vendors or contractors and not managed by the site. They can bypass the firewall and give a direct way into the zone.", "m": "Keep an inventory of all external connections (CM 1). Manage routers centrally: change default passwords, disable unused services, restrict management access. Search regularly for unauthorised modems and routers.", "a": "T0822 External Remote Services; T0883 Internet Accessible Device", "r": "3-3 SR 5.2; 2-1 CM 1; 2-1 NET 3", "p": "High", "s": "SL 1", "fr": "FR5 Restricted data flow", "i": "Loss of segmentation", "f": "5"}, {"id": "PL-S01", "c": "S", "t": "Rogue device on the wireless network used by target", "d": "Plant wireless networks can be reached from outside the fence. A rogue access point or a device with a stolen key can join the network used by the target.", "m": "Use strong wireless authentication and manage join keys. Separate wireless into its own zone behind a firewall. Monitor for rogue access points (NET 2).", "a": "T0860 Wireless Compromise; T0887 Wireless Sniffing", "r": "3-3 SR 1.6; 2-1 NET 2; 2-4 SP.04", "p": "High", "s": "SL 2", "fr": "FR1 Identification and authentication control", "i": "Manipulation of control; Loss of view", "f": "1"}, {"id": "PL-S02", "c": "S", "t": "Stolen or reused credentials used for remote access by source", "d": "Remote access accounts are a favourite target. Phished, reused or leaked credentials let an attacker log in as the source from anywhere.", "m": "Require multi-factor authentication for all remote access. Use individual named accounts, never shared vendor accounts. Restrict access by source address and time window. Review remote access logs.", "a": "T0822 External Remote Services; T0859 Valid Accounts", "r": "3-3 SR 1.13; 2-1 NET 3; 2-4 SP.07", "p": "High", "s": "SL 2", "fr": "FR1 Identification and authentication control", "i": "Full compromise", "f": "5"}, {"id": "PL-E05", "c": "E", "t": "Always-on or unsupervised access by source", "d": "the source can connect whenever it wants, without approval or supervision. A compromise of the vendor or integrator becomes a compromise of the plant.", "m": "Enable third-party access only on request, approved by operations and time-limited. Record or supervise sessions. Limit each third party to the assets it supports. Include security requirements in service contracts (2-4).", "a": "T0822 External Remote Services; T0886 Remote Services", "r": "3-3 SR 2.6; 2-1 NET 3; 2-4 SP.07", "p": "High", "s": "SL 2", "fr": "FR2 Use control", "i": "Full compromise", "f": "5"}, {"id": "PL-T02", "c": "T", "t": "Remote takeover of the operator or engineering session on target", "d": "An attacker with remote desktop or remote access to the target can operate the process exactly as an operator or engineer would, for example changing chemical dosing setpoints.", "m": "Do not allow remote control of operator stations without on-site approval. Prefer view-only remote access. Alarm on remote sessions. Keep engineering limits and interlocks in the controller, not only in the HMI.", "a": "T0822 External Remote Services; T0823 Graphical User Interface; T0831 Manipulation of Control", "r": "3-3 SR 2.1; 3-3 SR 1.13; 2-1 NET 3", "p": "High", "s": "SL 2", "fr": "FR2 Use control", "i": "Safety; Environmental; Manipulation of control", "f": "5"}, {"id": "PL-T03", "c": "T", "t": "Changes by source to target not covered by security requirements", "d": "Work done by the source (new equipment, upgrades, maintenance) may reintroduce default passwords, open ports or unpatched software if security requirements are not part of the contract and acceptance tests.", "m": "Specify IEC 62443-2-4 capabilities in contracts. Check security settings at factory and site acceptance tests. Require hand-over documentation of accounts, ports and software versions.", "a": "T0862 Supply Chain Compromise; T1694.001 Insecure Credentials: Default Credentials", "r": "2-4 SP.02; 2-4 SP.03; 2-1 ORG 1", "p": "Medium", "s": "SL 1", "fr": "FR3 System integrity", "i": "Attack enablement", "f": "5"}, {"id": "PL-E06", "c": "E", "t": "Known vulnerabilities on target not patched", "d": "Security patches for the target are not installed or their status is unknown, so publicly known vulnerabilities can be exploited.", "m": "Keep a patch status register for every asset (COMP 3). Qualify and install vendor-approved patches in planned outages. Where patching must wait, document compensating controls such as stricter filtering at the conduit.", "a": "T0866 Exploitation of Remote Services; T0890 Exploitation for Privilege Escalation", "r": "3-3 SR 3.2; 2-1 COMP 3; 2-4 SP.11", "p": "High", "s": "SL 1", "fr": "FR3 System integrity", "i": "Full compromise", "f": "3"}, {"id": "PL-E07", "c": "E", "t": "target is end of life and cannot be secured by patching", "d": "the target runs software or firmware that the vendor no longer supports. Vulnerabilities will stay open for the rest of its life in the plant.", "m": "Isolate the asset in its own zone with strict conduit rules. Disable unused services. Add monitoring. Plan replacement in the asset lifecycle budget and record the accepted risk.", "a": "T0866 Exploitation of Remote Services; T0890 Exploitation for Privilege Escalation", "r": "2-1 COMP 3; 3-2 ZCR 5; 2-1 CM 1", "p": "High", "s": "SL 1", "fr": "FR3 System integrity", "i": "Full compromise", "f": "3"}, {"id": "PL-T04", "c": "T", "t": "Malware can run on target", "d": "the target has no malware protection or application allow-listing, so malware arriving by network, USB or a vendor laptop runs unchecked.", "m": "Use application allow-listing or vendor-qualified anti-malware (COMP 2). Keep signatures updated through an OT update server. Block execution from removable media.", "a": "T0863 User Execution; T0847 Replication Through Removable Media; T1701 Command and Scripting Interpreter", "r": "3-3 SR 3.2; 2-1 COMP 2; 2-4 SP.10", "p": "High", "s": "SL 1", "fr": "FR3 System integrity", "i": "Full compromise; Production loss", "f": "4"}, {"id": "PL-E08", "c": "E", "t": "target runs with default or unhardened configuration", "d": "the target was installed with vendor defaults: unused services and ports open, default settings and no security baseline applied.", "m": "Apply the site hardening baseline (vendor security guide, CIS-type benchmark). Disable unused ports, services and accounts. Check configuration against the baseline after every change (CM 1).", "a": "T0866 Exploitation of Remote Services; T1694.001 Insecure Credentials: Default Credentials", "r": "3-3 SR 7.7; 3-3 SR 7.6; 2-1 COMP 1; 2-4 SP.03", "p": "Medium", "s": "SL 1", "fr": "FR7 Resource availability", "i": "Attack enablement", "f": "3"}, {"id": "PL-S03", "c": "S", "t": "Default, shared or generic accounts in use on target", "d": "Logins on the target use default, shared or generic accounts. Passwords are widely known, rarely changed and cannot be tied to a person.", "m": "Change all default passwords at commissioning. Use individual accounts where the system supports them. Where shared accounts cannot be avoided, control the password in a vault and log who checked it out.", "a": "T1694.001 Insecure Credentials: Default Credentials; T0859 Valid Accounts", "r": "3-3 SR 1.1; 2-1 USER 1; 2-4 SP.09", "p": "High", "s": "SL 1", "fr": "FR1 Identification and authentication control", "i": "Unauthorized access", "f": "3"}, {"id": "PL-S04", "c": "S", "t": "Leavers' and contractors' accounts still active on target", "d": "Accounts of staff who left, former contractors or commissioning engineers often stay active on the target for years and can be misused.", "m": "Run a joiner-mover-leaver process that covers OT systems. Review OT accounts at least yearly. Set expiry dates on contractor accounts. Remove commissioning accounts at hand-over.", "a": "T0859 Valid Accounts", "r": "3-3 SR 1.3; 2-1 USER 1; 2-4 SP.09", "p": "Medium", "s": "SL 1", "fr": "FR1 Identification and authentication control", "i": "Unauthorized access", "f": "3"}, {"id": "PL-R01", "c": "R", "t": "Attacks on target would not be detected", "d": "Security events from the target are not collected or reviewed, and its network traffic is not monitored. An intrusion could continue for months before anyone notices.", "m": "Forward security events to a central log server or SIEM. Deploy passive OT network monitoring on the zone. Define who reviews alerts and how fast (EVENT 1).", "a": "T0872 Indicator Removal on Host; T0846 Remote System Discovery", "r": "3-3 SR 6.2; 2-1 EVENT 1; 2-4 SP.08", "p": "Medium", "s": "SL 2", "fr": "FR6 Timely response to events", "i": "Detection; Recovery time", "f": "3"}, {"id": "PL-D02", "c": "D", "t": "target cannot be restored quickly after ransomware or failure", "d": "No tested backup exists for the target, or the restore has never been tried. After ransomware, a wiper or a hardware failure the plant may run without it for days or weeks.", "m": "Back up programs, configurations and system images (AVAIL 2). Keep an offline copy. Test restores on a schedule and record the restore time. Store installation media and licences.", "a": "T0809 Data Destruction; T0828 Loss of Productivity and Revenue", "r": "3-3 SR 7.3; 2-1 AVAIL 2; 2-4 SP.12", "p": "High", "s": "SL 1", "fr": "FR7 Resource availability", "i": "Production loss; Recovery time", "f": "3"}, {"id": "PL-E09", "c": "E", "t": "Security capability of target is below the zone target", "d": "The capability security level (SL-C) of the target is lower than the target security level (SL-T) of its zone, or has not been checked. The zone cannot reach its target without extra measures.", "m": "Compare SL-C with SL-T for every asset (3-2 ZCR 5). Where SL-C is lower, add compensating countermeasures (filtering, monitoring, physical protection) and document them, or replace the asset.", "a": "T0866 Exploitation of Remote Services", "r": "3-3 SR 5.2; 3-2 ZCR 5; 3-2 ZCR 6", "p": "Medium", "s": "SL 2", "fr": "FR5 Restricted data flow", "i": "Residual risk above tolerable", "f": "3"}, {"id": "PL-D03", "c": "D", "t": "Ransomware spreads to target and stops operations", "d": "Ransomware entering the plant can spread across Windows hosts through shared accounts, file shares and remote services, encrypting the target and forcing a shutdown.", "m": "Limit lateral movement: host firewalls, no shared admin accounts, separate OT domain. Keep offline backups. Prepare and exercise a plan to run the process without the affected hosts.", "a": "T0809 Data Destruction; T0828 Loss of Productivity and Revenue; T0826 Loss of Availability", "r": "3-3 SR 5.1; 2-1 AVAIL 2; 2-1 EVENT 1", "p": "High", "s": "SL 1", "fr": "FR5 Restricted data flow", "i": "Production loss; Financial", "f": "4"}, {"id": "PL-T05", "c": "T", "t": "Cyber attack on target could drive the process to a hazardous state", "d": "If the target is manipulated, the process could exceed safe limits (overdosing, overpressure, overflow). The question is whether non-programmable safeguards still prevent the hazard.", "m": "Run a cyber-HAZOP or consequence analysis for this controller. Confirm that the worst cases are covered by safeguards an attacker cannot change remotely (mechanical relief, hard-wired trips, independent SIS). Record the scenario reference.", "a": "T0831 Manipulation of Control; T0836 Modify Parameter; T0827 Loss of Control; T0879 Damage to Property", "r": "3-3 SR 3.6; 3-2 ZCR 5; IEC 61511-1 8.2.4", "p": "High", "s": "SL 2", "fr": "FR3 System integrity", "i": "Safety; Environmental; Equipment damage", "f": "2"}, {"id": "PL-T06", "c": "T", "t": "Unauthorised or unmanaged change to logic or configuration of target", "d": "Changes to logic, setpoints or configuration of the target are not controlled by management of change. A malicious or careless change would not be noticed until the process misbehaves.", "m": "Apply management of change to OT changes. Compare running logic with the approved version regularly. Use controller key switches or write-protection. Keep a change log with who, what and why (CM 1).", "a": "T0889 Modify Program; T0843 Program Download; T0836 Modify Parameter", "r": "3-3 SR 2.1; 2-1 CM 1; 2-4 SP.06", "p": "High", "s": "SL 1", "fr": "FR2 Use control", "i": "Safety; Product quality", "f": "2"}, {"id": "PL-T07", "c": "T", "t": "Safety function target disabled or altered by a cyber attack", "d": "A cyber attack on the safety system the target could disable trips or change trip points, so a hazardous event is no longer prevented (TRITON).", "m": "Carry out the SIS security risk assessment required by IEC 61511-1 8.2.4. Keep the SIS in its own zone. Use the key switch in Run, and control bypasses and maintenance overrides with procedures and alarms.", "a": "T0880 Loss of Safety; T0837 Loss of Protection; T0889 Modify Program", "r": "IEC 61511-1 8.2.4; 2-4 SP.05; 3-3 SR 5.1", "p": "High", "s": "SL 3", "fr": "FR3 System integrity", "i": "Safety; Environmental", "f": "2"}, {"id": "PL-E10", "c": "E", "t": "Safety system target reachable from the control zone", "d": "the target accepts traffic from outside the safety zone. A compromise of the control system could reach the safety function, so the two layers are no longer independent.", "m": "Separate the SIS in its own zone with a dedicated conduit. Allow read-only traffic from the BPCS where possible. Keep the SIS engineering station inside the safety zone and disconnected when not in use.", "a": "T0880 Loss of Safety; T0886 Remote Services", "r": "3-3 SR 5.1; IEC 61511-1 8.2.4; 2-4 SP.05", "p": "High", "s": "SL 3", "fr": "FR5 Restricted data flow", "i": "Safety", "f": "5"}, {"id": "PL-D04", "c": "D", "t": "Loss of view or control on target without a manual fallback", "d": "If the target is lost to an attack or failure, operators may not be able to run or safely shut down the process if no manual operating procedures exist or they are not practised.", "m": "Write and exercise procedures for running or shutting down the process without the control system. Provide local panels or hard-wired indications for critical values. Include the scenario in incident response exercises.", "a": "T0829 Loss of View; T0815 Denial of View; T0827 Loss of Control", "r": "3-3 SR 7.1; 2-1 AVAIL 1; 2-1 EVENT 1", "p": "High", "s": "SL 1", "fr": "FR7 Resource availability", "i": "Loss of view; Safety; Production loss", "f": "2"}, {"id": "PL-T08", "c": "T", "t": "Alarms on target suppressed or not acted on", "d": "An attacker who suppresses or floods alarms on the target can hide an attack or an abnormal process condition from operators.", "m": "Control alarm configuration and shelving through management of change. Monitor alarm settings for changes. Make critical alarms independent of the SCADA system where the consequence is high.", "a": "T0878 Alarm Suppression; T0838 Modify Alarm Settings", "r": "3-3 SR 2.1; 2-1 CM 1", "p": "Medium", "s": "SL 2", "fr": "FR2 Use control", "i": "Safety; Loss of view", "f": "2"}, {"id": "PL-D05", "c": "D", "t": "Failure of target cuts essential communication", "d": "the target may be a single point of failure. An attack, a misconfiguration or a failed update could cut communication for a whole zone.", "m": "Provide redundancy for network devices that carry essential traffic. Back up device configurations. Test changes before applying them and keep spare units.", "a": "T0814 Denial of Service; T0826 Loss of Availability", "r": "3-3 SR 7.1; 2-1 AVAIL 1; 2-1 AVAIL 2", "p": "Medium", "s": "SL 1", "fr": "FR7 Resource availability", "i": "Loss of view; Loss of control", "f": "2"}, {"id": "PL-E11", "c": "E", "t": "Conduit rules on target too permissive or not reviewed", "d": "Firewall rules on the target tend to grow over time: any-any rules, temporary vendor rules that stay, unused rules. Each one weakens the zone separation.", "m": "Review conduit rules at least yearly and after projects. Require a documented reason and owner for every rule. Remove temporary rules on an expiry date. Alert on rule changes.", "a": "T0884 Connection Proxy; T0885 Commonly Used Port", "r": "3-3 SR 5.2; 2-1 NET 1; 2-4 SP.03", "p": "High", "s": "SL 1", "fr": "FR5 Restricted data flow", "i": "Loss of segmentation", "f": "2"}, {"id": "PL-D06", "c": "D", "t": "IT security scanning from source disrupts target", "d": "Vulnerability scans or discovery tools run from the source can crash or slow fragile controllers like the target.", "m": "Exclude Level 0 to 2 devices from IT scanning. Use passive asset discovery in OT. Test any active query in a lab first and run it only in agreed windows.", "a": "T0814 Denial of Service", "r": "3-3 SR 7.1; 2-1 ORG 2", "p": "Medium", "s": "SL 1", "fr": "FR7 Resource availability", "i": "Loss of availability; Production loss", "f": "5"}, {"id": "PL-T09", "c": "T", "t": "Malware brought to target on USB media or a visiting laptop", "d": "USB drives, contractor laptops and other transient devices connected to the target are a common way malware reaches air-gapped or isolated plant networks (Stuxnet).", "m": "Control portable media and transient devices (COMP 1): scan at a kiosk before use, use company-owned media only, block unknown USB devices, and keep a register of transient devices and their owners.", "a": "T0847 Replication Through Removable Media; T0864 Transient Cyber Asset", "r": "3-3 SR 2.3; 2-1 COMP 1; 2-4 SP.10", "p": "High", "s": "SL 1", "fr": "FR2 Use control", "i": "Full compromise", "f": "5"}, {"id": "PL-S05", "c": "S", "t": "source tricked into giving access to target", "d": "the source may not recognise phishing, social engineering or pretext phone calls. A single successful lure can give an attacker valid access to the target.", "m": "Give OT-specific security awareness training to operators, engineers and contractors (ORG 1). Teach staff to verify unexpected remote support requests. Report suspicious events without blame.", "a": "T0865 Spearphishing Attachment; T0859 Valid Accounts", "r": "2-1 ORG 1; 2-4 SP.01", "p": "Medium", "s": "SL 1", "fr": "FR1 Identification and authentication control", "i": "Unauthorized access", "f": "5"}, {"id": "PL-E12", "c": "E", "t": "Insider misuse of privileges by source on target", "d": "A disgruntled, coerced or careless the source could misuse legitimate privileges on the target.", "m": "Grant least privilege by role (USER 2). Require approval and a second person for critical changes. Review privileged actions. Include OT roles in background checks and leaver processes.", "a": "T0859 Valid Accounts", "r": "3-3 SR 2.1; 2-1 USER 2; 2-1 ORG 1", "p": "Medium", "s": "SL 2", "fr": "FR2 Use control", "i": "Safety; Loss of control", "f": "5"}, {"id": "PL-R02", "c": "R", "t": "Actions by source on target cannot be traced to a person", "d": "Because the target uses shared accounts, it is not possible to tell which person made a change or issued a command.", "m": "Use individual accounts, or log who used a shared account and when. Keep an operator action journal and retain logs long enough for investigations.", "a": "T0859 Valid Accounts; T0872 Indicator Removal on Host", "r": "3-3 SR 2.8; 3-3 SR 1.1; 2-1 USER 1", "p": "Medium", "s": "SL 1", "fr": "FR2 Use control", "i": "Forensics; Compliance", "f": "5"}, {"id": "PL-I03", "c": "I", "t": "Plant drawings, programs or process history stolen from target", "d": "Engineering projects, network drawings, backups and process history on the target tell an attacker how the plant works and where it is weak.", "m": "Classify plant documentation and restrict access (DATA 1). Encrypt backups and laptops. Control what is replicated to the business network and to vendors.", "a": "T0882 Theft of Operational Information; T0811 Data from Information Repositories", "r": "3-3 SR 4.1; 2-1 DATA 1", "p": "Medium", "s": "SL 2", "fr": "FR4 Data confidentiality", "i": "Confidentiality; Attack enablement", "f": "2"}, {"id": "PL-D07", "c": "D", "t": "Backups in target encrypted or deleted together with the plant systems", "d": "If the target is reachable from the same network and accounts as the systems it protects, ransomware will encrypt or delete the backups too.", "m": "Keep at least one offline or immutable copy. Use separate credentials for the backup system. Test restores from the offline copy.", "a": "T0809 Data Destruction", "r": "3-3 SR 7.3; 2-1 AVAIL 2; 2-4 SP.12", "p": "High", "s": "SL 1", "fr": "FR7 Resource availability", "i": "Recovery time; Production loss", "f": "8"}, {"id": "PL-D07R", "c": "D", "t": "Backups in source encrypted or deleted together with the plant systems", "d": "If the source is reachable from the same network and accounts as the systems it protects, ransomware will encrypt or delete the backups too.", "m": "Keep at least one offline or immutable copy. Use separate credentials for the backup system. Test restores from the offline copy.", "a": "T0809 Data Destruction", "r": "3-3 SR 7.3; 2-1 AVAIL 2; 2-4 SP.12", "p": "High", "s": "SL 1", "fr": "FR7 Resource availability", "i": "Recovery time; Production loss", "f": "8s"}, {"id": "PL-R03", "c": "R", "t": "Security alerts from source not reviewed or acted on", "d": "Events reach the target but nobody is responsible for reviewing them, or there is no plan for what to do when an OT alert fires.", "m": "Assign alert review to a named team with response times. Write an OT incident response plan with operations, safety and the vendors. Exercise it at least yearly (EVENT 1).", "a": "T0872 Indicator Removal on Host", "r": "3-3 SR 6.1; 2-1 EVENT 1; 2-4 SP.08", "p": "Medium", "s": "SL 2", "fr": "FR6 Timely response to events", "i": "Detection; Recovery time", "f": "2"}, {"id": "PL-T10", "c": "T", "t": "Physical access to target at an unattended or open location", "d": "Someone with physical access to the target (remote station, field cabinet, open plant area) can connect a laptop, insert media, reset the device or tamper with wiring.", "m": "Lock cabinets and buildings, use door and cabinet intrusion alarms, and monitor remote sites (ORG 3). Disable unused ports. Alarm on device restarts and link changes.", "a": "T0864 Transient Cyber Asset; T0816 Device Restart/Shutdown", "r": "3-3 SR 2.3; 2-1 ORG 3", "p": "Medium", "s": "SL 2", "fr": "FR2 Use control", "i": "Loss of control; Equipment damage", "f": "3"}, {"id": "PL-E13", "c": "E", "t": "Compromise of cloud or vendor service source affects target", "d": "The plant depends on the source. If that service is compromised, it may push commands or configuration into the plant or leak plant data.", "m": "Keep cloud connections outbound-only and read-only where possible. Require local approval for any write from the cloud. Include the provider in supplier risk assessment and contracts.", "a": "T0862 Supply Chain Compromise; T1692.001 Unauthorized Message: Command Message", "r": "3-3 SR 5.2; 2-1 ORG 1; 2-4 SP.02", "p": "Medium", "s": "SL 2", "fr": "FR5 Restricted data flow", "i": "Loss of control; Confidentiality", "f": "5"}, {"id": "PL-T11", "c": "T", "t": "Wiring between source and target tampered with in the field", "d": "The signal from the source to the target runs through field wiring, junction boxes or marshalling cabinets. Someone with physical access can inject, cut or bridge it and change the process or defeat a safety function without touching the network.", "m": "Lock field cabinets and junction boxes and alarm their doors (2-1 ORG 3). Use monitored, fail-safe inputs for safety functions (IEC 61511-1 11.6). Include field wiring in site security walk-downs.", "a": "T0831 Manipulation of Control; T0880 Loss of Safety", "r": "3-3 SR 3.1; 2-1 ORG 3; IEC 61511-1 8.2.4", "p": "Medium", "s": "SL 2", "fr": "FR3 System integrity", "i": "Manipulation of control; Safety", "f": "7"}]};
